import{_ as t,o as d,c as o,a3 as r}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Resellers — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Resellers — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/resellers"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Resellers — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/resellers"}]]},"headers":[],"relativePath":"developer-guide/resellers.md","filePath":"developer-guide/resellers.md","lastUpdated":1787680328000}'),s={name:"developer-guide/resellers.md"};function l(a,e,i,c,n,p){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="resellers-—-developer-guide" tabindex="-1">Resellers — Developer Guide <a class="header-anchor" href="#resellers-—-developer-guide" aria-label="Permalink to &quot;Resellers — Developer Guide&quot;">​</a></h1><p>Phase 1 Sales module. Slug <code>resellers</code>, middleware <code>module:resellers</code>, permissions <code>resellers.*</code>. Hard catalog dependency on <strong>Payments</strong>. Companion ledger: <a href="/developer-guide/reseller-payouts">Reseller Payouts</a>.</p><p>Prefer copying Vendors/Companies assignee patterns over inventing new ones.</p><h2 id="backend-layout" tabindex="-1">Backend layout <a class="header-anchor" href="#backend-layout" aria-label="Permalink to &quot;Backend layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Path</th></tr></thead><tbody><tr><td>Model</td><td><code>app/Models/Reseller.php</code></td></tr><tr><td>Enums</td><td><code>ResellerStatusEnum</code>, <code>ResellerActivityTypeEnum</code></td></tr><tr><td>Models (notes/timeline)</td><td><code>ResellerNote</code>, <code>ResellerActivity</code></td></tr><tr><td>Service</td><td><code>app/Services/Tenant/ResellerService.php</code> (+ <code>ScopesToAssignee</code>)</td></tr><tr><td>Controller</td><td><code>app/Http/Controllers/Tenant/Api/V1/ResellerController.php</code></td></tr><tr><td>Requests</td><td><code>app/Http/Requests/Tenant/Api/V1/Reseller/*</code></td></tr><tr><td>Resources</td><td><code>app/Http/Resources/Tenant/Api/V1/Reseller/*</code></td></tr><tr><td>Policy</td><td><code>app/Policies/ResellerPolicy.php</code></td></tr><tr><td>Events</td><td><code>app/Events/Reseller*.php</code> (incl. <code>ResellerNoteAdded</code>)</td></tr><tr><td>Subscriber</td><td><code>app/Listeners/ResellerEventSubscriber.php</code> (platform audit)</td></tr><tr><td>Link rule</td><td><code>app/Rules/LinkableReseller.php</code> (invoice <code>reseller_id</code>)</td></tr><tr><td>Assignee rule</td><td><code>app/Rules/EligibleResellerAssignee.php</code></td></tr><tr><td>Tests</td><td><code>ResellerTest.php</code>, <code>ResellerInviteTest.php</code>, <code>ResellerNotesTimelineTest.php</code></td></tr></tbody></table><h2 id="domain-notes" tabindex="-1">Domain notes <a class="header-anchor" href="#domain-notes" aria-label="Permalink to &quot;Domain notes&quot;">​</a></h2><ul><li>Soft deletes; route binding uses <code>withTrashed()</code> for restore/force.</li><li>Status enum: <code>active</code> | <code>inactive</code> (default <code>active</code>).</li><li>Scalar <code>notes</code> on <code>resellers</code> is the profile field. Threaded notes live in <code>reseller_notes</code> and are serialized as <code>note_entries</code> (relationship <code>noteEntries()</code>) to avoid colliding with the scalar.</li><li>Domain timeline: <code>reseller_activities</code> via <code>ResellerService::recordActivity</code> / <code>timeline</code>. Types include created, updated, assigned, note_added, login_invited, deleted, restored.</li><li>Rates: <code>commission_rate</code>, <code>owner_commission_rate</code> — <code>decimal(5,2)</code>, validated 0–100 on store/update.</li><li>Assignee scoping via <code>ScopesToAssignee</code> with <code>resellers.assign</code>. Without assign (and not superadmin): list/stats/view limited to <code>assigned_to = actor</code> <strong>or</strong> <code>user_id = actor</code>. Update without assign is assignee-only (linked login cannot update via that path unless also assignee).</li><li><code>resellers.force.delete</code> is not on default admin/manager/staff maps — owner/superadmin only.</li><li><strong>Invite login</strong> (<code>ResellerService::inviteLogin</code>): requires no existing <code>user_id</code>; creates a tenant user via <code>TenantUserService</code> with role <code>[&#39;reseller&#39;]</code> only (<code>exclude_from_lead_auto_assign</code>, no employee, no website leads); unique email per tenant; unique <code>(tenant_id, user_id)</code> on <code>resellers</code>.</li><li>Protected default role <code>reseller</code> (see <code>config/tenant-protected-roles.php</code>) — ensures invited partners cannot escalate via role assignment APIs that block protected names.</li><li>Invoice link: optional <code>customer_invoices.reseller_id</code> validated with <code>LinkableReseller</code> (entitlement + assignee scope unless <code>resellers.assign</code> / superadmin).</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>config/tenant-permissions.php</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>resellers.view | create | update | delete | restore | force.delete | assign | invite</span></span></code></pre></div><p>Default role map (<code>config/tenant-default-role-permissions.php</code>):</p><table tabindex="0"><thead><tr><th>Role</th><th>Grants</th></tr></thead><tbody><tr><td>admin</td><td>view–restore, assign, invite (+ payouts all) — not force.delete</td></tr><tr><td>manager</td><td>view, create, update, assign, invite (+ payouts view/approve)</td></tr><tr><td>staff</td><td>view (+ payouts view)</td></tr><tr><td>reseller</td><td>view (+ payouts view)</td></tr></tbody></table><p>Routes use <code>module:resellers</code> then <code>can:resellers.*</code> / policies.</p><h2 id="api-tenant" tabindex="-1">API (tenant) <a class="header-anchor" href="#api-tenant" aria-label="Permalink to &quot;API (tenant)&quot;">​</a></h2><p>Base: <code>/api/tenant/v1</code> — full reference <a href="/api/tenant-v1-resellers">tenant-v1-resellers.md</a>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/resellers</code></td><td>view</td></tr><tr><td>GET</td><td><code>/resellers/stats</code></td><td>view</td></tr><tr><td>GET</td><td><code>/resellers/{reseller}</code></td><td>view</td></tr><tr><td>POST</td><td><code>/resellers</code></td><td>create</td></tr><tr><td>PUT</td><td><code>/resellers/{reseller}</code></td><td>update</td></tr><tr><td>DELETE</td><td><code>/resellers/{reseller}</code></td><td>delete</td></tr><tr><td>POST</td><td><code>/resellers/{reseller}/restore</code></td><td>restore</td></tr><tr><td>DELETE</td><td><code>/resellers/{reseller}/force</code></td><td>force.delete</td></tr><tr><td>POST</td><td><code>/resellers/{reseller}/assign</code></td><td>assign</td></tr><tr><td>POST</td><td><code>/resellers/{reseller}/invite-login</code></td><td>invite</td></tr><tr><td>GET</td><td><code>/resellers/{reseller}/timeline</code></td><td>view</td></tr><tr><td>POST</td><td><code>/resellers/{reseller}/notes</code></td><td>update</td></tr></tbody></table><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><p>SPA mirrors Vendors detail pattern: <code>src/pages/resellers/</code> with Overview | Notes | Activity | Access tabs (<code>reseller-detail-sheet.tsx</code>). Service: <code>resellerService</code> (<code>addNote</code>, <code>timeline</code>). Nav: <code>permission: resellers.view</code> + <code>module: &#39;resellers&#39;</code> under Sales.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Tenant/Reseller</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Suite</th><th>Location</th></tr></thead><tbody><tr><td>Pest</td><td><code>tests/Feature/Tenant/Reseller/</code> (<code>ResellerTest</code>, <code>ResellerInviteTest</code>, <code>ResellerNotesTimelineTest</code>)</td></tr></tbody></table><h2 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to &quot;Logging&quot;">​</a></h2><ul><li>Spatie <code>LogsActivity</code> on <code>Reseller</code> (log name <code>resellers</code>)</li><li>Domain timeline via <code>reseller_activities</code> (<code>ResellerService::recordActivity</code>)</li><li><code>PlatformAuditService</code> via <code>ResellerEventSubscriber</code>: <code>reseller_created</code>, <code>reseller_updated</code>, <code>reseller_deleted</code>, <code>reseller_assigned</code>, <code>reseller_login_invited</code>, <code>reseller_note_added</code></li></ul><h2 id="deferred" tabindex="-1">Deferred <a class="header-anchor" href="#deferred" aria-label="Permalink to &quot;Deferred&quot;">​</a></h2><ul><li>Cross-workspace identity (Central-linked reseller person across tenants)</li><li>Reseller portal / branded partner UX</li><li>Dashboard widgets, import/export</li></ul>',25)])])}const m=t(s,[["render",l]]);export{u as __pageData,m as default};
